// ===================== ERC rules 16:9 — helpers (1920×1080) =====================
const BG=`<rect width="1920" height="1080" fill="url(#studio)"/>`;
const kw=(id,x,y,txt,size,col,hl,f='B')=>`<g data-k="${id}">${hl?`<rect x="${x-txt.length*size*.29-24}" y="${y-size*.95}" width="${txt.length*size*.58+48}" height="${size*1.3}" rx="${size*.3}" fill="${hl}"/>`:''}${f=='L'?lat(x,y,txt,size,col,800):tx(x,y,txt,size,col,800)}</g>`;
const kwU=(q,id,lt,b,t)=>{const e=q(id);if(!e)return;if(lt<b){T(e,{o:0,s:.6});return}const p=cl((lt-b)/.42);T(e,{s:L(.55,1,eb(p)),o:cl(p*3),y:L(30,0,eo(p))})};
// landscape road map (top right) — ids P+'RR', P+'RD'+i, P+'RG'+i
const RL=['নিষিদ্ধ','শর্তসাপেক্ষ','জালিয়াতি','হস্তান্তর','ভয় নেই'],RCOL=[C.r,C.o,C.b,C.t,C.g];
const rd=(P)=>`<g data-k="${P}RR"><rect x="700" y="62" width="1000" height="10" rx="5" fill="#fff" opacity=".8"/>${RL.map((l,i)=>`<g data-k="${P}RG${i}"><circle data-k="${P}RD${i}" cx="${700+i*250}" cy="67" r="28" fill="#cbd5e1" stroke="#fff" stroke-width="5"/>${lat(700+i*250,79,String(i+1),28,'#fff',800)}${tx(700+i*250,128,l,24,C.ink,800)}</g>`).join('')}</g>`;
const rdU=(q,P,lt,t,cur)=>{T(q(P+'RR'),{o:cl(lt*3)});for(let i=0;i<5;i++){const c=q(P+'RD'+i);if(c)c.setAttribute('fill',i<cur-1?C.g:i==cur-1?RCOL[i]:'#cbd5e1');T(q(P+'RG'+i),{s:i==cur-1?L(.6,1.15,pe(lt,0,.5))+Math.sin(t*3)*.03:1})}};
// point title card (left, y 170–280)
const ttl2=(P,n,txt,col)=>`<g data-k="${P}TT">${card(80,170,780,110,'#fff',36)}<circle cx="150" cy="225" r="40" fill="${col}"/>${tx(150,243,n,48,'#fff',800)}${tx(210,243,txt,44,C.ink,800,'start')}</g>`;
const ttlU=(q,P,lt,t)=>popIn(q(P+'TT'),pe(lt,.15,.5),t,0,30,2);
// art
const ercCard=(x,y,w,h)=>`<g>${card(x,y,w,h,'#fffbeb',24)}<rect x="${x+14}" y="${y+14}" width="${w-28}" height="${h-28}" rx="14" fill="none" stroke="#c9a227" stroke-width="4"/><rect x="${x+14}" y="${y+14}" width="${w-28}" height="${h*.22}" rx="14" fill="${C.g}"/>${lat(x+w/2,y+14+h*.15,'ERC',Math.min(60,h*.16),'#fff',800)}${lat(x+w/2,y+h*.45,'Export Registration Certificate',Math.min(26,w*.045),C.ink,800)}<rect x="${x+w*.15}" y="${y+h*.55}" width="${w*.5}" height="12" rx="6" fill="#e7dcb8"/><rect x="${x+w*.15}" y="${y+h*.63}" width="${w*.35}" height="12" rx="6" fill="#e7dcb8"/><circle cx="${x+w-80}" cy="${y+h-80}" r="44" fill="${C.g}" opacity=".9"/><circle cx="${x+w-80}" cy="${y+h-80}" r="32" fill="none" stroke="#fff" stroke-width="4" stroke-dasharray="6 5"/></g>`;
const gun=(x,y,s=1,c='#334155')=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M-70 -24 H60 V-4 H-10 L-24 40 H-52 L-40 -4 H-70Z" fill="${c}"/><rect x="40" y="-34" width="14" height="10" fill="${c}"/><circle cx="-6" cy="8" r="10" fill="none" stroke="${c}" stroke-width="6"/></g>`;
const radio=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><circle r="60" fill="${C.y}"/>${[0,1,2].map(i=>`<path d="M0 0 L${Math.cos(i*2.094-1.57)*52} ${Math.sin(i*2.094-1.57)*52} A52 52 0 0 1 ${Math.cos(i*2.094-1.57+1.047)*52} ${Math.sin(i*2.094-1.57+1.047)*52}Z" fill="#1f2937"/>`).join('')}<circle r="14" fill="${C.y}"/><circle r="9" fill="#1f2937"/></g>`;
const vase=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M-20 -60 H20 V-44 Q50 -20 44 20 Q38 56 0 60 Q-38 56 -44 20 Q-50 -20 -20 -44Z" fill="#b45309"/><path d="M-40 6 H40" stroke="#fde68a" stroke-width="6"/><path d="M-36 24 H36" stroke="#fde68a" stroke-width="4"/></g>`;
const skull=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M-46 -6 Q-46 -60 0 -60 Q46 -60 46 -6 Q46 22 26 30 V52 H-26 V30 Q-46 22 -46 -6Z" fill="#e5e7eb" stroke="#64748b" stroke-width="5"/><circle cx="-18" cy="-6" r="12" fill="#334155"/><circle cx="18" cy="-6" r="12" fill="#334155"/><path d="M-12 40 V52 M0 40 V52 M12 40 V52" stroke="#64748b" stroke-width="4"/></g>`;
const seeds=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M-56 -30 Q-60 50 0 56 Q60 50 56 -30 Q0 -44 -56 -30Z" fill="${C.jute}"/><path d="M-56 -30 Q0 -14 56 -30" stroke="${C.juteD}" stroke-width="6" fill="none"/>${Array.from({length:9},(_,i)=>`<ellipse cx="${-30+(i%3)*30}" cy="${-36-(Math.floor(i/3))*10}" rx="8" ry="5" fill="#5b3b12"/>`).join('')}</g>`;
const shrimp2=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M50 -26 Q76 16 34 42 Q-8 58 -42 34 L-66 50 L-58 16 L-74 0 L-42 8 Q-8 26 16 8 Q34 -6 26 -26Z" fill="#f28c5a"/>${[0,1,2].map(i=>`<path d="M${-8+i*18} ${30-i*8} q5 -12 0 -22" stroke="#fff" stroke-width="4" fill="none" opacity=".7"/>`).join('')}</g>`;
const rice=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M-50 -40 Q-60 50 0 56 Q60 50 50 -40Z" fill="#f5f5f4" stroke="#a8a29e" stroke-width="5"/>${Array.from({length:7},(_,i)=>`<ellipse cx="${-30+i*10}" cy="${-46+(i%2)*6}" rx="6" ry="3" fill="#d6d3d1"/>`).join('')}${tx(0,20,'চাল',28,'#78716c',800)}</g>`;
const fish2=(x,y,s=1,col='#5b8db3')=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M-90 0 Q-30 -52 50 -14 L96 -46 L86 0 L96 46 L50 14 Q-30 52 -90 0Z" fill="${col}"/><circle cx="-56" cy="-8" r="8" fill="#0f172a"/></g>`;
const leaf2=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M0 70 Q-80 10 -40 -50 Q0 -90 40 -50 Q80 10 0 70Z" fill="#3f9b2f"/><path d="M0 -60 V70 M0 0 L-28 -20 M0 24 L28 4" stroke="#bde5a8" stroke-width="5" fill="none"/></g>`;
const slash=(x,y,r)=>`<g><circle cx="${x}" cy="${y}" r="${r}" fill="none" stroke="${C.r}" stroke-width="12"/><path d="M${x-r*.7} ${y+r*.7} L${x+r*.7} ${y-r*.7}" stroke="${C.r}" stroke-width="12"/></g>`;
const tap=(id)=>`<circle cx="0" cy="0" r="30" fill="#ffffff" opacity=".85" stroke="${C.ink}" stroke-width="6"/><circle data-k="${id}" cx="0" cy="0" r="30" fill="none" stroke="#fff" stroke-width="6"/>`;
